//如果纵坐标大于等于最低点
jumpValue = -4;
//增变量为负值
if (y <= LOWEST_Y - JUMP_HIGHT) {
//如果跳过最高点
jumpValue = 4;
//增变量为正值
}
y += jumpValue;
//纵坐标发生变化
if (y >= LOWEST_Y){
//如果再次落地
jumpState = false;
//停止跳跃
}
}
